import {clamp,stageAt} from './svg.js';
export const topic={number:'05',title:'焊點電遷移與空洞成長',question:'固態焊點裡，空洞為什麼愈來愈大？',duration:34,overview:27,simplification:'選用Chang等人研究的Cu-SAC-L材料及Bump 1方向：上方薄Al導線、Cu UBM、SAC1205（Sn–1.2Ag–0.5Cu，另含0.05Ni）、下方Cu。上端陰極、下端陽極；電子向下，傳統電流向上。單一剖面與圖符為定性改編，電子與原子速度差、空洞尺寸及累積層均放大，不求解電流密度或質量平衡。終態仍有金屬通路，只顯示電阻上升趨勢；原研究未直接量測單顆焊點電阻。停電不使空洞癒合。',supplement:'<p>電遷移是固態金屬中原子通量的失衡。快速移動的小藍圓代表電子，慢速橙方塊是原子淨輸運的追蹤標記；白色缺口才是空洞。圖符不是原子尺度的碰撞實景。</p>',sources:[{title:'Chang et al. · Discrete Void Formation (2017)',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC5738397/',claim:'全文、材料表及圖說：Cu-SAC-L、電子向下的Bump 1、上界面空洞萌生、成長與合併。'}]};
export const stages=[{start:0,key:3,title:'完整的固態接點',explain:'薄Al導線通往上方Cu UBM，SAC焊料連接下方Cu。此時接點完整。',detail:'材料保持固態。金屬層與空白背景的邊界從頭到尾可追蹤。'},{start:5,key:8,title:'電子向下，電流向上',explain:'上端陰極、下端陽極。藍色小圓向下代表電子；外側向上箭頭代表傳統電流。',detail:'兩種方向定義相反。外側箭頭是方向圖例，不是額外導線。'},{start:10,key:15,title:'原子淨輸運與空洞萌生',explain:'橙色方塊緩慢移向陽極端並留在下方累積區；上界面的原子供需失衡留下空洞。',detail:'原子標記與電子不同。原子有下方累積或參與反應的去向，不直接消失。'},{start:18,key:22,title:'空洞合併，電流繞行',explain:'上界面的白色空洞長大並連成較長缺口。電子路徑避開缺口，集中經過右側剩餘金屬。',detail:'仍有金屬路徑，所以是退化而非斷路。電阻上升只表達定性趨勢。'},{start:25,key:27,title:'停止負載，損傷仍在',explain:'移動的電子圖符停止顯示，但原先的空洞、下方累積與剩餘接點形狀仍然保留。',detail:'停電不把受損材料修復回完整接點。沒有熔化或沸騰。'},{start:30,key:32,title:'受損試件退場，換新試件',explain:'整個受損試件移出，新完整試件另外進場。',detail:'循環接縫不會倒轉空洞成長。'}];
export function stateAt(t){const index=stageAt(t,stages);return{t,index,title:stages[index].title,damage:clamp((t-10)/15),power:t>=5&&t<25,caption:t<5?'固態焊料 · 完整接點':t<10?'上端陰極 − · 下端陽極 +':t<18?'慢速原子淨輸運 → 下端累積':t<25?'通路收窄 · 電阻上升趨勢':t<30?'停止負載 · 空洞仍保留':'受損試件與新試件分別進出'};}
